/**
 * Resolve both body handles and client-provided ids against current membership.
 * Composer suggestions can be stale, so no supplied id is trusted on its own.
 */
async function resolveMentionedUsers(
  actor: Actor,
  body: string,
  clientProvided: readonly UserId[],
): Promise<readonly UserId[]> {
  const members: MemberWithUser[] = [];
  let cursor: string | null = null;
  do {
    const page = await memberRepo.listMembers({
      orgId: actor.orgId,
      status: "active",
      limit: MENTION_LOOKUP_LIMIT,
      cursor,
    });
    members.push(...page.items.filter(
      (member) => isInOrgScope(actor, member) && isLive(member) && member.status === "active",
    ));
    cursor = page.nextCursor;
  } while (cursor !== null);

  const currentUserIds = new Set(members.map((member) => member.userId));
  const resolved = resolveMentions(body, members);
  return [...new Set([
    ...resolved,
    ...clientProvided.filter((id) => currentUserIds.has(id)),
  ])];
